    "gs.folderNameNoSlash": { zh: "文件夹名不能含 /（要建嵌套请进对应文件夹再点新建）", en: "Folder name cannot contain / (to nest, enter the target folder first, then create)", ja: "フォルダ名に / を含められません（入れ子を作るには対象フォルダに入ってから作成してください）" },
    "gs.folderNamePlaceholder": { zh: "文件夹名", en: "Folder name", ja: "フォルダ名" },
    "gs.folderNeedSignin": { zh: "图库离线（未登录或权限失效），无法新建文件夹", en: "Gallery is offline (not signed in / permission lost) — can't create a folder", ja: "ギャラリーがオフライン（未ログイン／権限切れ）のためフォルダを作成できません" },
    "gs.footUsage": { zh: "作品占用：{size}（{count} 件）", en: "Artwork usage: {size} ({count} items)", ja: "作品の使用量：{size}（{count} 件）" },
    "gs.footUsageTitle": { zh: "浏览器分配上限约 {size}；当前 {pct}% 已用（含 SW 缓存等）", en: "Browser allocation cap ~{size}; {pct}% used now (incl. SW cache, etc.)", ja: "ブラウザ割り当て上限は約 {size}；現在 {pct}% 使用中（SW キャッシュ等を含む）" },
    "gs.lockLabel": { zh: "锁定加密作品（忘掉密码）", en: "Lock encrypted works (forget password)", ja: "暗号化作品をロック（パスワードを破棄）" },
    "gs.locked": { zh: "已锁定加密作品（密码已从内存清除）", en: "Encrypted works locked (password cleared from memory)", ja: "暗号化作品をロックしました（パスワードをメモリから消去）" },
    "gs.newFolderDefault": { zh: "新文件夹", en: "New folder", ja: "新しいフォルダ" },
    "gs.newFolderTitle": { zh: "新建文件夹", en: "New folder", ja: "新しいフォルダ" },
    "gs.pwRecorded": { zh: "已记下密码（打开加密作品时验证）", en: "Password recorded (verified when opening an encrypted work)", ja: "パスワードを記録しました（暗号化作品を開くときに検証）" },
    "gs.pwResetDone": { zh: "已重置。下次加密时设置新密码", en: "Reset done. Set a new password next time you encrypt", ja: "リセットしました。次回の暗号化時に新パスワードを設定します" },
    "gs.pwWrongRetry": { zh: "密码不对，再试一次", en: "Wrong password, try again", ja: "パスワードが違います。もう一度" },
    "gs.quotaCritical": { zh: "本地存储 {pct}% 已满 — 立即去图库卸载不常用的作品", en: "Local storage {pct}% full — go to the gallery now and offload works you rarely use", ja: "ローカルストレージが {pct}% 使用済み — 今すぐギャラリーで使わない作品を退避してください" },
    "gs.quotaWarn": { zh: "本地存储 {pct}% 已用 — 建议在图库整理", en: "Local storage {pct}% used — consider tidying up in the gallery", ja: "ローカルストレージが {pct}% 使用済み — ギャラリーで整理することをおすすめします" },
    "gs.resetPwMsg": { zh: "重置后下次加密可设新密码；但已有加密作品仍是旧密码，无法用新密码解锁。确定重置？", en: "After reset you can set a new password for future encryption; existing encrypted works keep the old password and cannot be unlocked with the new one. Reset?", ja: "リセット後は新しいパスワードを設定できますが、既存の暗号化作品は旧パスワードのままです。リセットしますか？" },
    "gs.resetPwTitle": { zh: "重置图库密码？", en: "Reset gallery password?", ja: "ギャラリーパスワードをリセット？" },
    "gs.unlockLabel": { zh: "解锁加密作品…", en: "Unlock encrypted works…", ja: "暗号化作品のロック解除…" },
    "gs.unlockNoLocalMsg": { zh: "本地暂无加密作品可验证——密码先收下，用到时自动验证", en: "No local encrypted work to verify against — the password is saved for now and verified automatically when needed", ja: "ローカルに検証できる暗号化作品がありません——パスワードは先に保存し、使用時に自動で検証します" },
    "gs.unlockTitle": { zh: "解锁加密作品", en: "Unlock encrypted works", ja: "暗号化作品のロック解除" },
    "gs.unlockVerifierMsg": { zh: "输入图库密码（跟账号走）。忘记 = 内容永久找不回，没有后门", en: "Enter the gallery password (tied to your account). If forgotten, content is unrecoverable — there is no backdoor", ja: "ギャラリーのパスワードを入力（アカウントに紐づく）。忘れた場合、内容は復元できません" },
    "gs.unlocked": { zh: "已解锁加密作品（密码只在内存，关页即忘）", en: "Encrypted works unlocked (password stays in memory only, forgotten on page close)", ja: "暗号化作品のロックを解除しました（パスワードはメモリのみ、ページを閉じると消去）" },
    "gs.usageUnknown": { zh: "占用：未知", en: "Usage: unknown", ja: "使用量：不明" },
    "gs.usedSuffix": { zh: " · 已用 {pct}%", en: " · {pct}% used", ja: " · {pct}% 使用" },
