        this._chipsEl.addEventListener("click", (e) => {
            const t = e.target;
            if (t.closest("[data-jump]")) {
                this._toggleJump();
                return;
            }
            const b = t.closest("[data-page]");
            if (b)
                this._page(parseInt(b.dataset.page, 10));
        });
        // 瞥一眼不能有代价（user 2026-09-29 同意）：用鼠标 / 手指点窗里的任何东西，都不许把键盘焦点从宿主那里拿走
        //   ——写作 app 里点一下参考窗就把软键盘收了，是在冷启动时添堵。拦的是「按下」的默认行为（挪焦点、起选区），
        //   click 照常触发；用 Tab 键走到这些按钮上不受影响。将来要让用户选中文字的卡，在内容上标 data-takes-focus 放行。
        //   **0.3.1（user 2026-09-30「这个看 focus 吧」）**：粘贴归焦点——窗身（画面 / 空态 / 拖把 / 手柄）按下就拿焦点
        //   （宿主元素 tabindex=0；宿主的 paste 监听看 hasFocus 分流），只有四个小钮（翻页 / ＋ / ×）仍不夺焦点：瞥一眼翻页零代价。
        const keepHostFocus = (e) => {
            const t = e.target;
            if (!t?.closest?.("button"))
                return; // 窗身 → 让浏览器把焦点落到 host（tabindex=0）
            e.preventDefault();
        };
        root.addEventListener("pointerdown", keepHostFocus);
        root.addEventListener("mousedown", keepHostFocus);
        // v134 touch resize 手柄（CSS resize:both 只支持鼠标）
        const grip = root.querySelector(".grip");
        grip.addEventListener("pointerdown", (e) => {
            e.preventDefault();
            e.stopPropagation();
            try {
                grip.setPointerCapture(e.pointerId);
            }
            catch { }
            const r = this.getBoundingClientRect();
            this._resizeDrag = { id: e.pointerId, sx: e.clientX, sy: e.clientY, w0: r.width, h0: r.height, l0: r.left, t0: r.top };
        });
