export const WP_REFERENCE_WINDOW_TAG = "wp-reference-window";
if (!customElements.get(WP_REFERENCE_WINDOW_TAG)) {
    customElements.define(WP_REFERENCE_WINDOW_TAG, WpReferenceWindow);
}
