// 参考窗的宿主适配层。created 2026-10-08 深夜 by Claude Opus 5.5（v0.8 参考窗纪元；对齐稿 = ai-docs/20261008-reference-window-alignment.md）
// user：「现在最卫生的是reference window然后还有实时预览」「mp3可以暂缓。现在主要就是对着截图打谱哈哈哈」
//   「文字也支持，反正就是无脑一包直接用。文字比如一些和声之类的东西都蛮有用的」。
//
// 参考窗本体 = 家族共享库 @internal/reference-window（牌组模型 + 默认视图 <wp-reference-window>）。**本文件是 MoonSinger 里唯一认识那个库的地方**
//   （test/reference-guard.test.ts 守着），样板 = WXHW src/reference-host.ts：
//   · 卡：库现有的图片卡 / 文字卡整包收（截图、和声笔记）；live / 链接卡这一版不接，别的种类库原样带着
//   · 存：`.moonsinger/references/` 整个目录（manifest.json + 每张卡的字节）经库的 encodeDeck / decodeDeck 进出，本文件只搬字节；
//     不放进 extras（extras 进撤销快照——参考窗不进撤销，同 WXHW），宿主拿 files() / rev() 存、拿 apply() 开
//   · 脏：加 / 删 / 挪卡 = 正经改动（编好字节之后 rev +1、onCards() 通知宿主）；开关窗 / 挪窗 / 翻卡 = 视图态（宿主存时顺手捞，不标脏）
//   · 清单比库新（DeckManifestTooNewError）→ 目录原样带着、存的时候原样写回、明说；不吞、不猜
//   · 图片原样存（家规「字节进出不走 canvas」；库也说没编码器就留原字节）；单张超过 4 MB 先问一句「存进歌里 / 取消」（家族批过的提醒线）
//     → 0.4.0（2026-10-09，v0.9.x）：图片 / 音频超过 1 MB 都问（user「3. 音频也超过1MB才问？」）：存进歌里 / 压一下（约 X MB；src/app/ref-transcode.ts 注入）/
//       只放内存（不存进歌里；读回来是空位，同名文件拖进来补上——user「然后能不能加RAM only，就是不落盘，每次重新上传」）/ 算了。
//       超过 4 MB 把「只放内存」排第一（user「这里可能是全家族仓我们唯一一个真的需要nudge用户」）。问的面板是宿主的（main.ts askImport），不用系统对话框。
//   · 音频卡（库 0.4.0）：播放 / 暂停 + 进度条；循环、速度 1 / 0.75 / 0.5（user「默认不开，moonsinger开」）；关窗、翻卡不停（user「不停」）
//   · 粘贴看焦点：窗有焦点 = 贴进窗；没有 = 宿主照旧（谱里贴简谱文字）
import { _t } from "../i18n/index.ts";
import "@internal/reference-window";
import type { WpReferenceWindow, RefMenuPort, RefPanelRect, RefImportQuestion, RefImportChoice } from "@internal/reference-window";
import { encodeDeck, decodeDeck, mimeForName, DeckManifestTooNewError } from "@internal/reference-window/deck";
import { togglePopupMenu } from "@internal/workbench-elements";
import { createRefTranscoder } from "./ref-transcode.ts";

const APP = "moonsinger";                          // 目录 = .moonsinger/references/（库按 app 名算）
const KINDS = ["image", "text", "audio", "video"] as const; // 这个宿主画得出来的（视频 = 参考窗 0.5.0 起）；其余的库原样带着
export const ASK_ABOVE = 1024 * 1024;              // 图片 / 音频 / 视频超过 1 MB 先问（存 / 压 / 只放内存 / 算了）；音频 / 视频默认只放内存（库 0.5.0，不覆盖）
export const RAM_ABOVE = 4 * 1024 * 1024;          // 超过 4 MB：问的时候「只放内存」排第一（技术方案批过的 4 MB 提醒线）
export type { RefImportQuestion, RefImportChoice };
/** 窗的位置 / 开着没有（视图态：存进 score.json 的 view.ref，不标脏、不进撤销）。 */
export interface RefPanel { open: boolean; left: number; top: number; width: number; height: number }

export interface ReferenceHostDeps {
  info(text: string): void;
  error(text: string): void;
  /** 顶栏下缘（浮窗不往上越过它）。 */
  topFloor(): number;
  /** 屏底被占掉的高度（竖屏时 pad 那一块 + iOS 键盘把视口顶起的一截）：拖 / 缩放 / 钳制都留出它，右下角的把手不躲到 pad 底下。 */
  bottomFloor(): number;
  /** 关窗 / Esc 之后焦点还给谱。 */
  focusScore(): void;
  /** 文件超过 1 MB：问存 / 压 / 只放内存 / 算了（应用内面板，不用系统对话框）。 */
  askImport(q: RefImportQuestion): Promise<RefImportChoice>;
  /** 卡片变了、字节已经编好（files() / rev() 已是新的）：宿主标脏、通知存档节律。 */
  onCards(): void;
  /** 修改锁（2026-11-10，参考窗 0.6.0 的 canEdit 口；家族修改锁标准「跟着文档存、但不进撤销的东西也要过同一处」）：现在让不让加 / 删 / 挪卡。
   *  翻页、缩放、开关窗不问（纯粹是看）。不给 = 永远让。 */
  canEdit?(): boolean;
  /** 被拒了（窗里的挪卡 / 删卡，或者从这头加卡）：宿主让门闪一下。 */
  onEditRefused?(): void;
}

export function createReferenceHost(d: ReferenceHostDeps) {
  const el = document.createElement("wp-reference-window") as WpReferenceWindow;
  el.className = "ref-window";
  const fileInput = document.createElement("input");
  fileInput.type = "file"; fileInput.multiple = true; fileInput.hidden = true; fileInput.accept = "image/*,audio/*,video/*,.txt,.md,text/plain,text/markdown";
  document.body.append(el, fileInput);

  let encoded: Record<string, Uint8Array> = {};      // 现在要存的那份字节（路径 → 字节；路径都在 .moonsinger/references/ 下）
  let rev = 0;                                         // 卡片改动的修订号（宿主拿它判脏）
  let seq = 0;                                         // 编码排队：后来的赢
  let carried = false;                                 // 清单比库新：encoded 是原样带着的，不从牌组重编
  let applying = false;                                // apply 期间牌组的 reset 不算用户改动
  let placed = false;                                  // 这首歌里开过窗（没开过 = view 里不写 ref）
  let pending: Promise<void> = Promise.resolve();

  // ── 注入 ──
  // 修改锁：窗里的挪卡 / 删卡由库的 canEdit 口问（不让 = 这一下什么都不做 + 发 editrefused）；从宿主这头加卡（导入 / 粘贴 / 拖放）在下面各个入口问 mayEdit
  const mayEdit = (): boolean => { if (d.canEdit?.() ?? true) return true; d.onEditRefused?.(); return false; };
  el.canEdit = () => d.canEdit?.() ?? true;
  el.addEventListener("editrefused", () => d.onEditRefused?.());
  el.menuPort = ((o) => togglePopupMenu(o)) as RefMenuPort;
  el.setAttribute("no-cloud", "");                     // 不从云盘选图（歌库不是图库；iPad 的「文件」已经能挑相册 / OneDrive）
  el.labels = {
    paste: _t("粘贴"), oneToOne: _t("原尺寸"), del: _t("删掉这张"), delConfirm: _t("再点一次删掉"), closeWin: _t("收起参考窗"),
    prev: _t("上一张"), next: _t("下一张"), menu: _t("参考窗菜单"), move: _t("点一下缩成小图标，按住拖动挪位置"), resize: _t("改大小"), resizeAria: _t("改大小"),
    moveEarlier: _t("往前挪"), moveLater: _t("往后挪"), jump: _t("跳到…"), kindNames: { image: _t("图片"), text: _t("文字"), audio: _t("音频"), video: _t("视频") }, linkMissing: _t("内容不在了"),
    load: _t("导入图片 / 音频 / 视频 / 文字…"), play: _t("播放"), pause: _t("暂停"), loop: _t("循环"), rate: _t("速度"),
    prevFrame: _t("上一帧"), nextFrame: _t("下一帧"),   // 参考窗 0.5.0 视频卡（图标 = 库里的 skip-prev / skip-next，user「逐帧按钮先不用」= 不另画）
    ram: _t("只放内存（不存进歌里）"), ramMissing: _t("只在内存里，没存进歌里——把这个文件拖进来，或者点 ＋ 重新导入，就补回这里"),
    minimize: _t("缩成小图标"), restore: _t("点一下恢复，按住拖动挪位置"),   // 参考窗 0.4.1（关窗那个已经叫「收起」，这里用「缩」区分）
  };
  el.audioRates = [1, 0.75, 0.5];   // 扒谱用（保音高）
  const transcoder = createRefTranscoder();
  const syncFloor = () => { el.topFloor = d.topFloor(); el.bottomFloor = d.bottomFloor(); if (el.open) el.reclamp(); };
  window.addEventListener("resize", syncFloor);

  // ── 牌组变化 → 编字节 → 脏 ──
  const reencode = () => {
    const my = ++seq;
    pending = (async () => {
      const out: Record<string, Uint8Array> = {};
      for (const [path, blob] of encodeDeck(el.deck.snapshot(), { app: APP })) out[path] = new Uint8Array(await blob.arrayBuffer());
      if (my !== seq) return;   // 又改过了：让后来的那次落
      encoded = out; carried = false; rev++;
      d.onCards();
    })();
  };
  el.deck.onChange((what) => { if (!applying && what.type === "cards") reencode(); });
  el.addEventListener("openchange", () => { if (el.open) { placed = true; syncFloor(); } });
  el.addEventListener("rectchange", () => { placed = true; });

  // ── ＋ 菜单 / 粘贴 / 拖放 ──
  el.addEventListener("requestload", () => { if (!mayEdit()) return; fileInput.value = ""; fileInput.click(); });
  fileInput.addEventListener("change", () => { const files = [...(fileInput.files ?? [])]; if (files.length) void importFiles(files); });
  el.addEventListener("requestpaste", () => { if (mayEdit()) void pasteFromClipboard(); });
  window.addEventListener("paste", (e) => {   // 粘贴看焦点（库 0.3.1）：窗有焦点 → 文件 / 文字进窗；没有 → 不管，宿主的粘贴照旧
    if (!el.hasFocus) return;
    const cd = e.clipboardData; if (!cd) return;
    e.preventDefault(); e.stopPropagation();
    if (!mayEdit()) return;
    const files = [...cd.files];
    if (files.length) { void importFiles(files); return; }
    const text = cd.getData("text/plain");
    if (text.trim()) { el.addText(text, { name: "" }); el.open = true; return; }
    d.error(_t("剪贴板里没有图片或文字"));
  }, true);
  el.addEventListener("dragover", (e) => { if (e.dataTransfer && Array.from(e.dataTransfer.types).includes("Files")) { e.preventDefault(); e.stopPropagation(); e.dataTransfer.dropEffect = "copy"; } });
  el.addEventListener("drop", (e) => { const files = [...(e.dataTransfer?.files ?? [])]; if (!files.length) return; e.preventDefault(); e.stopPropagation(); if (mayEdit()) void importFiles(files); });
  el.addEventListener("notice", (e) => {
    const n = (e as CustomEvent).detail as { level: string; code: string; name?: string; message: string };
    d.error(n.code === "decode-failed" ? _t("这张图这个浏览器打不开{name}", { name: n.name ? `：${n.name}` : "" }) : _t("参考窗：{message}", { message: n.message }));
  });
  el.addEventListener("keydown", (e) => { if (e.key === "Escape") { e.preventDefault(); d.focusScore(); } });   // Esc = 焦点回谱（窗留着）

  /** 导入（菜单 / 拖放 / 粘贴文件）：库的漏斗（嗅种类 → 超过 1 MB 问 → 原样 / 压 / 只放内存 / 不要），结果如实说。 */
  async function importFiles(files: File[]): Promise<void> {
    const r = await el.importFiles(files, { kinds: KINDS, transcoder, ask: (q) => d.askImport(q), askAbove: { image: ASK_ABOVE, audio: ASK_ABOVE, video: ASK_ABOVE }, ramAbove: RAM_ABOVE });   // defaultRam 不传 = 库 0.5.0 的默认：音频 / 视频只放内存（当次有效），图片 / 文字随歌
    for (const k of r.skipped) {
      if (k.why === "unsupported") d.error(_t("认不出：{name}（参考窗收图片、音频和文字）", { name: k.name }));
      else if (k.why === "failed") d.error(_t("没加上：{name}（{message}）", { name: k.name, message: k.message ?? _t("出错了") }));
    }
    const said = [r.added.length ? _t("加了 {n} 张", { n: r.added.length }) : "", r.filled.length ? _t("补回 {n} 张（只放内存的空位）", { n: r.filled.length }) : "", ...r.notes].filter(Boolean);
    if (r.added.length || r.filled.length) { el.focus({ preventScroll: true }); d.info(_t("参考窗：{p}", { p: said.join("；") })); }
  }
  async function pasteFromClipboard(): Promise<void> {
    try {
      for (const it of await navigator.clipboard.read()) {
        const img = it.types.find((x) => x.startsWith("image/"));
        if (img) { await importFiles([new File([await it.getType(img)], _t("粘贴.{p}", { p: img.split("/")[1] ?? "png" }), { type: img })]); return; }
        if (it.types.includes("text/plain")) { const text = await (await it.getType("text/plain")).text(); if (text.trim()) { el.addText(text, { name: "" }); el.open = true; return; } }
      }
      d.error(_t("剪贴板里没有图片或文字"));
    } catch {
      try { const text = await navigator.clipboard.readText(); if (text.trim()) { el.addText(text, { name: "" }); el.open = true; return; } } catch { /* 浏览器不给读 */ }
      d.error(_t("读不了剪贴板：点一下参考窗，再按 Ctrl / ⌘+V"));
    }
  }

  return {
    /** 现在要存的字节（路径 → 字节）。 */
    files: (): Record<string, Uint8Array> => encoded,
    /** 卡片改动的修订号。 */
    rev: () => rev,
    /** 编码还在跑的话等它（存之前调，免得刚加的卡没赶上）。 */
    settled: () => pending,
    /** 开一首歌：files = 歌里 `.moonsinger/references/` 下的全部字节；panel = 视图态里记的窗（没有 = 收着）。 */
    async apply(files: Record<string, Uint8Array>, panel: RefPanel | null): Promise<void> {
      seq++; applying = true; carried = false; encoded = { ...files }; placed = !!panel;
      try {
        if (!Object.keys(files).length) el.deck.clear();
        else {
          const decoded = await decodeDeck({ app: APP, knownKinds: KINDS, getFile: (p) => { const b = files[p]; return b ? new Blob([b as unknown as BlobPart], { type: mimeForName(p) }) : null; } });
          el.deck.restore(decoded);
          // 库 0.5.0 清单拍子：minor 比这版新 = 照样读写，告诉用户一次（不弹窗不拦）；patch 比这版新 = 静默；major 比这版新 = 下面的 DeckManifestTooNewError
          if (decoded.verdict === "newer-minor") d.info(_t("这首歌的参考窗是更新版本的 app 存的：这版没有的功能保存时不丢，只是看不到"));
        }
      } catch (e) {
        el.deck.clear();
        if (e instanceof DeckManifestTooNewError) { carried = true; d.error(_t("这首歌的参考窗是更新版本的 app 存的（参考清单第 {fileVersion} 版，这一版认到第 {libVersion} 版）：原样留着、存的时候原样写回，这里先不显示", { fileVersion: e.fileVersion, libVersion: e.libVersion })); }
        else { carried = true; d.error(_t("参考窗读不出来：{Error}（字节原样留着、存的时候原样写回）", { Error: (e as Error).message })); }
      } finally { applying = false; }
      if (panel) el.rect = { left: panel.left, top: panel.top, width: panel.width, height: panel.height };
      el.open = !!panel?.open && !carried;
      if (el.open) syncFloor();
    },
    /** 视图态：开过窗才有。 */
    panel(): RefPanel | null { if (!placed) return null; const r: RefPanelRect = el.rect; return { open: el.open, left: Math.round(r.left), top: Math.round(r.top), width: Math.round(r.width), height: Math.round(r.height) }; },
    /** 菜单入口：开 = 顺手给焦点（开窗 → Ctrl+V 一步到位）；关 = 焦点回谱。 */
    toggle(): void {
      if (carried) { d.error(_t("这首歌的参考窗是更新版本的 app 存的，这一版先不显示（原样留着）")); return; }
      el.open = !el.open;
      if (el.open) { placed = true; syncFloor(); el.focus({ preventScroll: true }); } else d.focusScore();
    },
    isOpen: () => el.open,
    hasFocus: () => el.hasFocus,
    count: () => el.deck.cards().length,
    /** pad 露 / 收、视口变了之后宿主调。 */
    relayout: syncFloor,
    /** 测试用：导入（同菜单那条路）。 */
    importFiles,
    el,
  };
}
export type ReferenceHost = ReturnType<typeof createReferenceHost>;
