// 牌组模型：参考窗里那一叠卡。零 DOM——node 直测；CatsUp 的 VR 视图、宿主自己重写的视图也从这里进。
// created 2026-09-29 by Claude Fable 5.1
// 契约出处 = 家族根 ai-docs/20260929-reference-window-tech-plan.md §3。
//
// 三条规矩：
//   1. 本模块不持久化、不联网、不碰 DOM。宿主用 snapshot() 把牌组拿走，写进自己的容器。
//   2. restore() 是载入恢复专用，静默；其余一切变更都通知 onChange（宿主据此同步清单、决定标不标脏）。
//   3. 这个宿主不认识的卡不进 cards（画不出来），但原样留在 carried 里，保存时原样写回。
function cloneView(v) {
    if (!v)
        return null;
    const ok = Number.isFinite(v.tx) && Number.isFinite(v.ty) && Number.isFinite(v.scale) && Number.isFinite(v.rot);
    return ok ? { tx: v.tx, ty: v.ty, scale: v.scale, rot: v.rot } : null;
}
function clonePlay(p) {
    if (!p || !Number.isFinite(p.t))
        return null;
    const fps = typeof p.fps === "number" && Number.isFinite(p.fps) && p.fps > 0 ? p.fps : undefined;
    return fps !== undefined ? { t: p.t, loop: !!p.loop, fps } : { t: p.t, loop: !!p.loop };
}
function cloneExtra(x) {
    if (!x || typeof x !== "object" || Array.isArray(x) || Object.keys(x).length === 0)
        return null;
    return JSON.parse(JSON.stringify(x));
}
function cloneCarried(c) {
    return { at: c.at, item: JSON.parse(JSON.stringify(c.item)), files: { ...c.files } };
}
function clampIndex(i, n) {
    if (n <= 0)
        return 0;
    if (!Number.isFinite(i))
        return 0;
    return Math.max(0, Math.min(n - 1, Math.trunc(i)));
}
export function createDeck() {
    let cards = [];
    let carried = [];
    let extra = {};
    let index = 0;
    let seq = 0;
    const listeners = new Set();
    const emit = (what) => {
        // 逐个调；一个监听者抛错不许拖垮别的监听者，也不许吞掉——收集后统一重抛第一个。
        let first = null, threw = false;
        for (const fn of [...listeners]) {
            try {
                fn(what);
            }
            catch (e) {
                if (!threw) {
                    threw = true;
                    first = e;
                }
            }
        }
        if (threw)
            throw first;
    };
    const make = (c) => ({
        id: `c${++seq}`,
        kind: c.kind,
        name: c.name ?? "",
        bytes: c.bytes ?? null,
        mime: c.mime ?? (c.bytes?.type || ""),
        target: c.target ?? null,
        vp: cloneView(c.vp),
        play: clonePlay(c.play),
        origin: c.origin ?? null,
        ram: c.ram && Number.isFinite(c.ram.bytes) ? { bytes: c.ram.bytes } : null,
        extra: cloneExtra(c.extra),
    });
    const copy = (c) => ({ ...c, vp: cloneView(c.vp), play: clonePlay(c.play), ram: c.ram ? { bytes: c.ram.bytes } : null, extra: cloneExtra(c.extra) });
    const deck = {
        get size() { return cards.length; },
        get index() { return index; },
        get current() { return cards[index] ?? null; },
        cards: () => cards,
        get: (id) => cards.find((c) => c.id === id) ?? null,
        indexOf: (id) => cards.findIndex((c) => c.id === id),
        snapshot: () => ({ index, cards: cards.map(copy), carried: carried.map(cloneCarried), extra: cloneExtra(extra) ?? {} }),
        restore(s) {
            if (!s || !Array.isArray(s.cards))
                throw new TypeError("Deck.restore expects { cards: [...] }");
            cards = s.cards.map((c) => {
                if (!c || typeof c.kind !== "string" || !c.kind)
                    throw new TypeError("Deck.restore: every card needs a non-empty string kind");
                return make(c);
            });
            carried = (s.carried ?? []).map(cloneCarried);
            extra = cloneExtra(s.extra) ?? {};
            index = clampIndex(s.index ?? 0, cards.length);
            emit({ type: "reset" });
            return cards.map((c) => c.id);
        },
        clear() {
            cards = [];
            carried = [];
            extra = {};
            index = 0;
            emit({ type: "reset" });
        },
        add(card, opts) {
            if (!card || typeof card.kind !== "string" || !card.kind)
                throw new TypeError("Deck.add: card needs a non-empty string kind");
            const c = make(card);
            cards.push(c);
            if (opts?.select ?? true)
                index = cards.length - 1;
            emit({ type: "cards" });
            return c.id;
        },
        remove(id) {
            const i = deck.indexOf(id);
            if (i < 0)
                return;
            cards.splice(i, 1);
            // 删的在当前之前 → 当前那张卡往前挪了一位，index 跟着减；删的就是当前 → 停在原位（看下一张），到尾则退一格。
            if (i < index)
                index -= 1;
            index = clampIndex(index, cards.length);
            emit({ type: "cards" });
        },
        move(id, toIndex) {
            const from = deck.indexOf(id);
            if (from < 0)
                return;
            const to = clampIndex(toIndex, cards.length);
            if (to === from)
                return;
            const viewing = cards[index]?.id ?? null;
            const [c] = cards.splice(from, 1);
            cards.splice(to, 0, c);
            if (viewing)
                index = deck.indexOf(viewing);
            emit({ type: "cards" });
        },
        select(i) {
            const next = clampIndex(i, cards.length);
            if (next === index)
                return;
            index = next;
            emit({ type: "view" });
        },
        setView(id, vp) {
            const c = deck.get(id);
            const v = cloneView(vp);
            if (!c || !v)
                return;
            const o = c.vp;
            if (o && o.tx === v.tx && o.ty === v.ty && o.scale === v.scale && o.rot === v.rot)
                return;
            c.vp = v;
            emit({ type: "view" });
        },
        setPlay(id, play) {
            const c = deck.get(id);
            const p = clonePlay(play);
            if (!c || !p)
                return;
            if (c.play && c.play.t === p.t && c.play.loop === p.loop && c.play.fps === p.fps)
                return;
            c.play = p;
            emit({ type: "view" });
        },
        setRam(id, on) {
            const c = deck.get(id);
            if (!c)
                return;
            if (on) {
                if (c.ram)
                    return;
                c.ram = { bytes: c.bytes?.size ?? 0 };
            }
            else {
                if (!c.ram || !c.bytes)
                    return;
                c.ram = null;
            }
            emit({ type: "cards" });
        },
        fill(id, bytes, mime) {
            const c = deck.get(id);
            if (!c || !c.ram)
                return;
            c.bytes = bytes;
            if (mime)
                c.mime = mime;
            emit({ type: "view" });
        },
        setTarget(id, target) {
            const c = deck.get(id);
            if (!c || c.target === target)
                return;
            c.target = target;
            emit({ type: "cards" });
            emit({ type: "invalidate", id });
        },
        invalidate(id) {
            if (deck.indexOf(id) < 0)
                return;
            emit({ type: "invalidate", id });
        },
        onChange(fn) {
            listeners.add(fn);
            return () => { listeners.delete(fn); };
        },
    };
    return deck;
}
