// 音级读法（toDegree / fromDegree）2026-11-11 搬到核心 src/score/degree.ts（简谱的画法和这里共用一份）；这里转手导出，老的 import 不用改。
export { toDegree, fromDegree } from "./degree.ts";
import { toDegree, fromDegree } from "./degree.ts";
const DUR_SUFFIX: [number, string][] = [[TPQ * 4, " - - -"], [TPQ * 3, " - -"], [TPQ * 2, " -"], [TPQ * 1.5, "."], [TPQ, ""], [TPQ * 0.75, "_."], [TPQ / 2, "_"], [TPQ / 4, "__"], [TPQ / 8, "___"]];
function durText(dur: number): string {
  const hit = DUR_SUFFIX.find(([d]) => d === dur);
  return hit ? hit[1] : `(${dur})`;
}
const accText = (a: number) => (a > 0 ? "#".repeat(a) : "b".repeat(-a));
const octText = (s: number) => (s > 0 ? "'".repeat(s) : ",".repeat(-s));
/** 一段 token → 简谱文字（相对 fifths）。 */
export function toJianpu(toks: Token[], fifths: number): string {
  const out: string[] = [];
  let f = fifths;
  for (const t of toks) {
    if (t.kind === "bar") { out.push(t.repeat === "start" ? "|:" : t.repeat === "end" ? `:|${t.times && t.times > 2 ? `x${t.times}` : ""}` : t.repeat === "both" ? `:|:${t.times && t.times > 2 ? `x${t.times}` : ""}` : t.style === "double" ? "||" : t.style === "final" ? "|]" : "|"); continue; }   // 反复小节线 = |: / :| / :|x3 / :|:；段落线 = ||、终止线 = |]（v0.9.32）
    if (t.kind === "nav") { out.push(t.what === "ending" ? `[${(t.nums ?? [1]).join(".")}.]` : `[${NAV_TEXT[t.what]}]`); continue; }   // 房子 = [1.] / [1.2.]；跳转 = [D.C.] [D.S. al Coda] [Segno]…
    if (t.kind === "key") { f = t.fifths; out.push(t.mode === "minor" ? `[6=${MINOR_LABEL[t.fifths] ?? t.fifths}]` : `[1=${KEY_LABEL[t.fifths] ?? t.fifths}]`); continue; }   // 小调写 la 是哪个音
    if (t.kind === "time") { out.push(`[${t.beats}/${t.beatType}]`); continue; }
    if (t.kind === "tempo") { out.push(`[T=${t.bpm}]`); continue; }
    if (t.kind === "clef" || t.kind === "ottava" || t.kind === "pedal") continue;   // 谱号 / 八度线 / 踏板（11-1）只管画、出声，不进简谱文字（app 内剪贴板带着原 token）
    if (t.kind === "dyn") { out.push(`[${t.value}]`); continue; }   // 力度 = [mf]（演奏法不进简谱文字；app 内剪贴板带着原 token）
    if (t.kind === "hairpin") { out.push(t.dir === "cresc" ? "[<]" : "[>]"); continue; }   // 渐强 / 渐弱 = [<] / [>]
    if (t.kind === "groove") { out.push(`[G=${t.style}${t.amount !== undefined && t.amount !== 1 ? `:${Math.round(t.amount * 100)}` : ""}${t.shift ? "/2-3" : ""}]`); continue; }   // /2-3 = 错开一小节   // 风格（拍子轻重）= [G=pop] / [G=pop:150]
    const suf = durText(t.dur), lead = suf.startsWith(" -") ? "" : suf, tail = suf.startsWith(" -") ? suf : "";
    if (t.kind === "rest") { out.push(`0${lead}${tail}`); continue; }
    const body = t.pitch ? allPitches(t).map((pp) => { const { degree, shift, acc } = toDegree(pp, f); return `${accText(acc)}${degree}${octText(shift)}`; }).join("&") : "x";   // 叠音 = 1&3&5（从高到低）
    const ly = t.lyric ? `/${t.lyric.replace(/\s+/g, "")}${t.hyph ? "-" : ""}` : "";
    out.push(`${t.tie ? "^" : ""}${body}${lead}${ly}${tail}`);
  }
  return out.join(" ");
}
/** 跳转记号的简谱文字（一个词里不能有空格：D.C._al_Fine）。 */
const NAV_TEXT: Record<Exclude<NavWhat, "ending">, string> = Object.fromEntries(Object.entries(NAV_LABEL).map(([k, v]) => [k, v.replace(/ /g, "_")])) as Record<Exclude<NavWhat, "ending">, string>;
const NAV_BY_TEXT: Record<string, Exclude<NavWhat, "ending">> = Object.fromEntries(Object.entries(NAV_TEXT).map(([k, v]) => [v, k as Exclude<NavWhat, "ending">]));
const KEY_BY_LABEL: Record<string, number> = Object.fromEntries(Object.entries(KEY_LABEL).map(([k, v]) => [v.replace("♭", "b").replace("♯", "#"), Number(k)]));
const MINOR_BY_LABEL: Record<string, number> = Object.fromEntries(Object.entries(MINOR_LABEL).map(([k, v]) => [v.replace("♭", "b").replace("♯", "#"), Number(k)]));
/** 简谱文字 → token（相对 fifths；读不懂的词 = 整段不认，返回 null——别把别人聊天里的话当谱）。id 从 0 起（贴的时候重编）。 */
export function fromJianpu(text: string, fifths: number): Token[] | null {
  const words = text.trim().split(/\s+/).filter(Boolean);
  if (!words.length) return null;
  const out: Token[] = []; let f = fifths, id = 0, n = 0;
  const lastTimed = (): Timed | null => { for (let i = out.length - 1; i >= 0; i--) { const t = out[i]; if (t.kind === "note" || t.kind === "rest") return t; } return null; };
  for (const w of words) {
    if (w === "|") { out.push({ kind: "bar", id: id++ }); continue; }
    if (w === "||" || w === "|]") { out.push({ kind: "bar", id: id++, style: w === "||" ? "double" : "final" }); continue; }
    let r = /^(\|:|:\|:|:\|)(?:x(\d+))?$/.exec(w);
    if (r) { const rep: Repeat = r[1] === "|:" ? "start" : r[1] === ":|" ? "end" : "both", tm = r[2] ? Number(r[2]) : 0; if (rep === "start" && tm) return null;
      out.push({ kind: "bar", id: id++, repeat: rep, ...(tm > 2 ? { times: tm } : {}) }); continue; }
    r = /^\[((?:\d+\.)+)\]$/.exec(w);
    if (r) { out.push({ kind: "nav", id: id++, what: "ending", nums: r[1].split(".").filter(Boolean).map(Number) }); continue; }
    const nav = /^\[(.+)\]$/.exec(w)?.[1], navWhat = nav ? NAV_BY_TEXT[nav] : undefined;
    if (navWhat) { out.push({ kind: "nav", id: id++, what: navWhat }); continue; }
    if (w === "-") { const t = lastTimed(); if (!t) return null; t.dur += TPQ; continue; }
    if (w === ",") continue;   // 老版本复制出来的「句」（单独一个逗号）：句号 v0.16.86 去掉了，跳过
    let m = /^\[1=([A-G][b#]?)\]$/.exec(w);
    if (m) { const k = KEY_BY_LABEL[m[1]]; if (k === undefined) return null; f = k; out.push({ kind: "key", id: id++, fifths: k }); continue; }
    m = /^\[6=([A-G][b#]?)\]$/.exec(w);
    if (m) { const k = MINOR_BY_LABEL[m[1]]; if (k === undefined) return null; f = k; out.push({ kind: "key", id: id++, fifths: k, mode: "minor" }); continue; }
    m = /^\[(\d+)\/(\d+)\]$/.exec(w);
    if (m) { out.push({ kind: "time", id: id++, beats: Number(m[1]), beatType: Number(m[2]) }); continue; }
    m = /^\[T=(\d+)\]$/.exec(w);
    if (m) { out.push({ kind: "tempo", id: id++, bpm: Number(m[1]) }); continue; }
    m = /^\[(ppp|pp|p|mp|mf|f|ff|fff)\]$/.exec(w);
    if (m) { out.push({ kind: "dyn", id: id++, value: m[1] as Dyn }); continue; }
    if (w === "[<]" || w === "[>]") { out.push({ kind: "hairpin", id: id++, dir: w === "[<]" ? "cresc" : "dim" }); continue; }
    m = /^\[G=([a-z][a-z0-9-]*)(?::(\d+))?(\/2-3)?\]$/.exec(w);
    if (m) { const a = m[2] ? Number(m[2]) / 100 : 1; out.push({ kind: "groove", id: id++, style: m[1], ...(a !== 1 ? { amount: a } : {}), ...(m[3] ? { shift: true as const } : {}) }); continue; }
    m = /^(\^?)((?:[#b]*[0-7x]['’,]*)(?:&[#b]*[1-7]['’,]*)*)(_{0,3})(\.?)(?:\((\d+)\))?(?:\/([^/\s]+?)(-?))?$/.exec(w);
    if (!m) return null;
    const [, tie, body, unders, dot, ticks, lyric, hyph] = m;
    let dur = ticks ? Number(ticks) : TPQ / 2 ** unders.length;
    if (dot && !ticks) dur *= 1.5;
    if (body === "0") { out.push({ kind: "rest", id: id++, dur }); n++; continue; }
    const heads = body.split("&").map((h) => { const hm = /^([#b]*)([0-7x])(['’,]*)$/.exec(h)!; const acc = hm[1] ? (hm[1][0] === "#" ? hm[1].length : -hm[1].length) : 0; const shift = [...hm[3]].reduce((a, c) => a + (c === "," ? -1 : 1), 0); return hm[2] === "x" ? null : fromDegree(Number(hm[2]), shift, acc, f); });
    const t0: NoteTok = { kind: "note", id: id++, pitch: null, dur, lyric: lyric ?? null };
    const t = heads[0] ? withPitches(t0, heads.filter((h): h is NonNullable<typeof h> => !!h)) : t0;
    if (hyph) t.hyph = true; if (tie) t.tie = true;
    out.push(t); n++;
  }
  return n ? out : null;
}
/** 选区开头 / 光标处生效的调（简谱文字相对它写 / 读）。 */
export const fifthsAtSel = (st: EditorState): number => keyAt(tr(st), st.sel ? st.sel.from : Math.max(0, st.caret - 1));
export { stepIndex };
