export function createDiskLedger() {
    let next = 0;
    const onDisk = new Map();
    const inFlight = new Map(); // 发出了、还没落盘（或失败）的保存号
    const flying = (name) => { let s = inFlight.get(name); if (!s) {
        s = new Set();
        inFlight.set(name, s);
    } return s; };
    const settle = (name, g) => {
        const s = inFlight.get(name);
        if (!s)
            return;
        s.delete(g);
        if (s.size === 0)
            inFlight.delete(name);
    };
    return {
        issue(name) { const g = ++next; flying(name).add(g); return g; },
        landed(name, g) { settle(name, g); onDisk.set(name, g); },
        failed(name, g) { settle(name, g); },
        wrote(name) { const g = ++next; onDisk.set(name, g); return g; },
        disk(name) { return onDisk.get(name) ?? 0; },
        settled(name, g) { return !inFlight.has(name) && (onDisk.get(name) ?? 0) === g; },
        pendingAfter(name, g) { const d = onDisk.get(name) ?? 0; return inFlight.has(name) || (d !== g && d >= 0); },
        forget(name) { onDisk.set(name, -(++next)); },
    };
}
