import { t } from "../core/text.js";
// StoreTextKey（库的 busy 文案 key）→ 本包文案 key。穷举 Record：库加 key 本表漏映 = 编译错。
const STORE_TEXT_KEYS = {
    "sync.pushing": "st.syncPushing", "file.renaming": "st.fileRenaming", "file.pulling": "st.filePulling", "cloud.checking": "st.cloudChecking",
    "file.deleting": "st.fileDeleting", "trash.restoring": "st.trashRestoring", "trash.purging": "st.trashPurging", "trash.emptyTrash": "st.trashEmptyTrash",
    "trash.emptyBackups": "st.trashEmptyBackups", "file.encrypting": "st.fileEncrypting", "file.decrypting": "st.fileDecrypting", "file.rekeying": "st.fileRekeying",
    "file.uploading": "st.fileUploading", "file.reuploading": "st.fileReuploading", "folder.creating": "st.folderCreating", "folder.deleting": "st.folderDeleting",
};
const QUIET_KEYS = new Set(["sync.pushing", "file.renaming"]);
export function storeUIFor(d) {
    const bare = d.stemOf ?? ((s) => s);
    let _quietDepth = 0, _quietNotice = null;
    async function quietBusy(label, fn) {
        _quietDepth++;
        if (_quietNotice?.isOpen())
            _quietNotice.setText(label);
        else
            _quietNotice = d.showNotice({ id: "store-quiet-busy", level: "info", text: label, dismissible: false, tapToDismiss: false });
        try {
            return await fn();
        }
        finally {
            _quietDepth--;
            if (_quietDepth <= 0) {
                _quietDepth = 0;
                _quietNotice?.close();
                _quietNotice = null;
            }
        }
    }
    return {
        busy: (label, fn, key) => (key && QUIET_KEYS.has(key) ? quietBusy(label, fn) : d.busy(label, fn)),
        text: (key, params) => d.text?.(key, params) ?? (STORE_TEXT_KEYS[key] ? t(STORE_TEXT_KEYS[key], params) : undefined),
        resolveConflict: async ({ name, occasion, cloudState }) => {
            const n = bare(name);
            // 0.7.2：按云端那一侧的状态换说法（store 0.18.2 cloudState）；三个词不变、主按钮 = 云端覆盖本地
            const gone = cloudState === "absent" || cloudState === "never";
            const pushTitle = gone ? t("cf.cloudGoneTitle") : t("cf.cloudNewerTitle");
            const pushBody = cloudState === "absent" ? t("cf.body.absent", { name: n }) : cloudState === "never" ? t("cf.body.never", { name: n })
                : cloudState === "unchanged" ? t("cf.body.unchanged", { name: n }) : t("cf.body.push", { name: n });
            const choice = occasion === "open"
                ? await d.sheets.lockSyncGate({ title: t("cf.cloudNewerTitle"), message: t("cf.body.open", { name: n }), note: t("cf.note.keptSafe"), showSpinner: false,
                    actions: [{ label: t("cf.act.openLocal"), value: "cancel", primary: true }, { label: t("cf.act.cloudWins"), value: "takeCloud" }] })
                : await d.sheets.lockSyncGate({ title: pushTitle, message: pushBody, note: t("cf.note.keptSafe"), showSpinner: false,
                    // 0.7.1：主按钮 = 云端覆盖本地（user 2026-10-16「默认云端才是 authority」「一切对齐」；此前主按钮是本地覆盖云端，挂机醒来顺手一点就把云端的新改动盖进备份箱）
                    actions: [{ label: t("cf.act.cloudWins"), value: "takeCloud", primary: true }, { label: t("cf.act.localWins"), value: "keepMine" }, { label: t("common.cancel"), value: "cancel" }] });
            return choice ?? "cancel";
        },
        // 0.8.10（store 2.2.2；user 2026-10-26「同意，反正不删就行了」）：改名 / 移动撞上「不知道云端旧的该不该搬」→ 先问人。搬走 = 进回收站（可恢复），不是删。
        resolveRenameOld: async ({ oldName, newName, reason }) => {
            const choice = await d.sheets.lockSyncGate({
                title: t("rn.title", { name: bare(oldName) }),
                message: reason === "diverged" ? t("rn.body.diverged", { from: bare(oldName), to: bare(newName) }) : t("rn.body.unknown", { from: bare(oldName), to: bare(newName) }),
                note: t("rn.note"), showSpinner: false,
                actions: [{ label: t("rn.act.trash"), value: "trash", primary: true }, { label: t("rn.act.keep"), value: "keep" }, { label: t("common.cancel"), value: "cancel" }],
            });
            return choice ?? "cancel";
        },
        reportError: (err, level) => {
            if (err?.name === "CloudNetworkError") {
                d.reportError(err, "log");
                d.reportError(new Error(t("err.cloudNetwork")), level ?? "error");
                return;
            }
            d.reportError(err, level ?? "error");
        },
        offlineEscape: () => {
            let onSkip;
            const probe = new Promise((res) => { onSkip = () => res(undefined); });
            void d.sheets.lockSyncGate({ title: t("cf.checkingCloud"), message: "", showSpinner: true, actions: [{ label: t("cf.skipToOffline"), value: "skip" }] }).then((v) => { if (v === "skip")
                onSkip(); });
            return { probe, settle: () => d.sheets.settleSyncGate(null) };
        },
    };
}
