// 图库数据面（WET 自 WeebPaint src/app-store.ts 的图库段，2026-09-09）：store.Item → GItem；当前夹订阅的路由 + 排序；搁置区（回收站 / 备份箱）映射。
// 库唯一列举面 = store.files.watchFolder（订阅当前夹）；⛔ 永不 list 全库（WeebPaint 2026-07-12 删 listGallery 的判决）。
// 0.6.0：哪些是文档、主干是什么、种类是什么全由 store.identifiers 说（宿主在 createStore 报的 docKinds 表）；本包不再收 isDoc / naming 钩子。
//   图片（WeebPaint 的云盘图片）仍是本包的策略（policy.isImage）：它们不是文档，store 不认识。
import { isCached } from "@internal/store";
import { ASIDE, asideItemFrom, sortAside } from "./model/aside.js";
import { isImagePath } from "./model/cloud-image-model.js";
import { naturalCompare } from "./model/natural-order.js";
import { timelineCompare, mergeTimeline } from "./model/timeline-order.js";
const basename = (p) => p.slice(p.lastIndexOf("/") + 1);
/** store.Item → GItem：切开身份取主干和种类 + **syncState 原样透传**（0.4.0：不派生 local/cloud/dirty… 布尔；状态的唯一源在 store）。不是文档 → null。 */
export function galleryItemFromStoreItem(it, ids) {
    const d = ids.parse(it.identifier);
    if (!d)
        return null;
    const g = { identifier: it.identifier, stem: d.stem, kind: d.kind, syncState: it.syncState };
    if (it.size != null)
        g.size = it.size;
    if (it.lastModified != null)
        g.lastModified = it.lastModified;
    // 0.9.0：库填好的三个事实原样带上（store 2.3.0 的星 / 收起、2.2.6 的 cloudSealed）；老版本的库没有这些字段 = 不带。
    const f = it;
    if (f.starred === true)
        g.starred = true;
    if (f.folded === true)
        g.folded = true;
    if (f.cloudSealed === true)
        g.cloudSealed = true;
    return g;
}
export function createGalleryDataFace(deps) {
    const isImage = deps.policy?.isImage ?? isImagePath;
    const requireStore = () => { const s = deps.store(); if (!s)
        throw new Error("gallery data face: no library attached"); return s; };
    const toImageItems = (items, ids) => items
        .filter((it) => !ids.parse(it.identifier) && isImage(it.identifier))
        .map((it) => ({ identifier: it.identifier, label: basename(it.identifier), size: it.size, lastModified: it.lastModified, cached: isCached(it.syncState) }))
        .sort((a, b) => (b.lastModified ?? 0) - (a.lastModified ?? 0) || naturalCompare(b.label, a.label));
    const toOtherItems = (items, ids) => items
        .filter((it) => !ids.parse(it.identifier) && !isImage(it.identifier))
        .map((it) => ({ identifier: it.identifier, label: basename(it.identifier), size: it.size, lastModified: it.lastModified }))
        .sort((a, b) => naturalCompare(a.label, b.label));
    const folderNamesOf = (folder, folders) => { const prefix = folder ? `${folder}/` : ""; return folders.map((f) => f.slice(prefix.length)).filter(Boolean).sort(naturalCompare); };
    return {
        /** 订阅当前夹：立即本地帧、云端到了同一 cb 再闪。作品和子夹合成一列时间线（0.8.12：子夹不再钉在最上面；规则 = core/model/timeline-order.ts）；
         *  图片按修改时间倒序；杂物显示不打开。 */
        watchFolder(folder, cb, opts) {
            const st = requireStore(), ids = st.identifiers;
            return st.files.watchFolder(folder, (snap) => {
                const items = snap.items.map((it) => galleryItemFromStoreItem(it, ids)).filter((g) => g != null).sort((a, b) => timelineCompare(a.stem, b.stem) || naturalCompare(b.identifier, a.identifier));
                const folderNames = folderNamesOf(folder, snap.folders);
                const images = toImageItems(snap.items, ids), others = toOtherItems(snap.items, ids);
                cb({ folder: snap.folder, items, images, others, folderNames, timeline: mergeTimeline(items, folderNames, images, others) }); // 0.9.2：图片 / 杂物也在时间线里（images / others 两个数组自己的顺序不变，别的消费方照旧）
            }, opts);
        },
        watchFolderImages(folder, cb) {
            const st = requireStore(), ids = st.identifiers;
            return st.files.watchFolder(folder, (snap) => cb({ folder: snap.folder, images: toImageItems(snap.items, ids), folderNames: folderNamesOf(folder, snap.folders) }));
        },
        openCloudImage: (identifier) => requireStore().file(identifier, { mode: "existing" }).open(),
        /** 搁置区（0.5.0；回收站 / 备份箱同一个面）：store 两端聚合的 TrashItem[] → AsideItem（只元数据，无 blob），新的在前。
         *  读哪个列表由 ASIDE 表定；列表只来自 store，宿主没有注入口。 */
        listAside: async (box) => {
            const st = requireStore();
            return sortAside((await ASIDE[box].list(st.files)).map((it) => asideItemFrom(box, it, st.identifiers)), naturalCompare);
        },
    };
}
