import { parseVersionStem, versionsOf } from "./versions.js";
/** 展开状态的键：细条 = "S:" + 这一串里第一份的身份；原作的各版 = "V:" + 原作的身份。 */
export const stripKey = (firstIdentifier) => `S:${firstIdentifier}`;
export const versionsKey = (originalIdentifier) => `V:${originalIdentifier}`;
export function foldTimeline(timeline, o) {
    const docs = timeline.filter((e) => e.type === "doc").map((e) => e.item);
    // ① 哪些是「有原作的版本」：按（种类, 原主干）找同夹里的原作。原作自己不能是另一份的版本名（避免链式挂靠）。
    const originals = new Map();
    for (const it of docs)
        if (!parseVersionStem(it.stem))
            originals.set(`${it.kind}\u0000${it.stem}`, it);
    const attached = new Set();
    for (const it of docs) {
        const v = parseVersionStem(it.stem);
        if (v && originals.has(`${it.kind}\u0000${v.base}`))
            attached.add(it.identifier);
    }
    const open = (key) => o.expandAll === true || o.isOpen(key);
    const rows = [];
    const pushDoc = (item, dim) => {
        const versions = parseVersionStem(item.stem) ? [] : versionsOf(item, docs);
        const versionsOpen = versions.length > 0 && open(versionsKey(item.identifier));
        rows.push({ type: "doc", item, versions, versionsOpen, dim, versionOf: null });
        if (versionsOpen)
            for (const v of versions)
                rows.push({ type: "doc", item: v, versions: [], versionsOpen: false, dim: true, versionOf: item.identifier });
    };
    let run = [];
    const flush = () => {
        if (!run.length)
            return;
        const key = stripKey(run[0].identifier), isOpen = open(key);
        rows.push({ type: "strip", key, count: run.length, open: isOpen });
        if (isOpen)
            for (const it of run)
                pushDoc(it, true);
        run = [];
    };
    for (const e of timeline) {
        if (e.type === "folder") {
            flush();
            rows.push({ type: "folder", name: e.name });
            continue;
        }
        if (e.type === "image" || e.type === "other") {
            flush();
            rows.push({ type: e.type, identifier: e.file.identifier });
            continue;
        }
        const it = e.item;
        if (attached.has(it.identifier))
            continue; // ① 跟着原作走
        if (it.folded || parseVersionStem(it.stem)) {
            run.push(it);
            continue;
        } // ② 手动收起的 / 原作不在的版本
        flush();
        pushDoc(it, false);
    }
    flush();
    return rows;
}
/** 这一夹里一共收起了几份（细条里的 + 收在原作底下的各版）。顶上「全部展开」那一条用。 */
export function foldedCount(timeline) {
    let n = 0;
    for (const e of timeline)
        if (e.type === "doc" && (e.item.folded || parseVersionStem(e.item.stem)))
            n++;
    return n;
}
