/** 记号那份 collection 的名字（云端 = `.${appId}/store.file-marks.json`）。带 `store.` 前缀 = 库自己的，app 别用这个名字开 collection。 */
export const MARKS_COLLECTION = "store.file-marks";
const clean = (v) => {
    const o = (v && typeof v === "object" ? v : {});
    const out = {};
    if (o.starred === true)
        out.starred = true;
    if (o.folded === true)
        out.folded = true;
    return out;
};
/** collection 懒开：第一次要用才开（开 = 建云端那份文件）。getCollection 由 create-store 给（走 store.collection 同一个工厂 → 单例、scaffold、dispose 都有人管）。 */
export function createMarks(cfg) {
    let coll = null, readyP = null, reconciling = false;
    const c = () => (coll ??= cfg.getCollection());
    const ready = () => (readyP ??= c().init());
    return {
        ready,
        get: (identifier) => (coll ? clean(coll.getItem(identifier)) : {}),
        async set(identifier, patch) {
            await ready();
            const cur = clean(c().getItem(identifier));
            const next = { ...cur };
            if (patch.starred === true)
                next.starred = true;
            else if (patch.starred === false)
                delete next.starred;
            if (patch.folded === true)
                next.folded = true;
            else if (patch.folded === false)
                delete next.folded;
            if (!!next.starred === !!cur.starred && !!next.folded === !!cur.folded)
                return; // 没变：不写（不白盖一次时间戳）
            if (next.starred || next.folded)
                c().setItem(identifier, next);
            else
                c().deleteItem(identifier);
            const r = await c().flushLocal(); // 人刚点的星：立刻落本机，不等防抖（关页也不丢）
            if (!r.ok)
                throw r.error instanceof Error ? r.error : new Error(`marks: local write failed for "${identifier}"`);
        },
        async rename(from, to) {
            await ready();
            const cur = clean(c().getItem(from));
            if (!cur.starred && !cur.folded)
                return;
            c().setItem(to, cur);
            c().deleteItem(from);
            const r = await c().flushLocal();
            if (!r.ok)
                throw r.error instanceof Error ? r.error : new Error(`marks: local write failed moving "${from}" → "${to}"`);
        },
        starredIdentifiers: () => (coll ? coll.entries().filter((e) => clean(e.value).starred).map((e) => e.id) : []),
        onChange: (cb) => c().onChange((ids) => cb(ids)),
        reconcile() {
            if (reconciling)
                return;
            reconciling = true;
            void ready().then(() => c().reconcileWithRemote()).then((r) => { if (r.status === "error")
                cfg.onError(r.error); }, cfg.onError).finally(() => { reconciling = false; });
        },
    };
}
